   368→	commonAncestorRoot, _, err := s.cfg.ForkChoiceStore.CommonAncestor(ctx, newHeadRoot, orphanedRoot)
   369→	switch {
   370→	// Exit early if there's no common ancestor and root doesn't exist, there would be nothing to save.
   371→	case errors.Is(err, forkchoice.ErrUnknownCommonAncestor):
   372→		return nil
   373→	case err != nil:
   374→		return err
   375→	}
   376→	for orphanedRoot != commonAncestorRoot {
   377→		if ctx.Err() != nil {
   378→			return ctx.Err()
   379→		}
