   381→		orphanedBlk, err := s.getBlock(ctx, orphanedRoot)
   382→		if err != nil {
   383→			return err
   384→		}
   385→		// If the block is an epoch older, break out of the loop since we can't include atts anyway.
   386→		// This prevents stuck within this for loop longer than necessary.
   387→		if orphanedBlk.Block().Slot()+params.BeaconConfig().SlotsPerEpoch <= s.CurrentSlot() {
   388→			break
   389→		}
   390→		for _, a := range orphanedBlk.Block().Body().Attestations() {
   391→			// if the attestation is one epoch older, it wouldn't been useful to save it.
   392→			if a.GetData().Slot+params.BeaconConfig().SlotsPerEpoch < s.CurrentSlot() {
   393→				continue
   394→			}
   395→			if features.Get().EnableExperimentalAttestationPool {
   396→				if err = s.cfg.AttestationCache.Add(a); err != nil {
   397→					return err
   398→				}
   399→			} else {
   400→				if orphanedBlk.Version() >= version.Electra {
   401→					if err = s.cfg.AttPool.SaveBlockAttestation(a); err != nil {
   402→						return err
   403→					}
   404→				} else if a.IsAggregated() {
   405→					if err = s.cfg.AttPool.SaveAggregatedAttestation(a); err != nil {
   406→						return err
   407→					}
   408→				} else {
   409→					if err = s.cfg.AttPool.SaveUnaggregatedAttestation(a); err != nil {
   410→						return err
   411→					}
   412→				}
   413→			}
   414→			saveOrphanedAttCount.Inc()
