   416→		for _, as := range orphanedBlk.Block().Body().AttesterSlashings() {
   417→			if err := s.cfg.SlashingPool.InsertAttesterSlashing(ctx, s.headStateReadOnly(ctx), as); err != nil {
   418→				log.WithError(err).Error("Could not insert reorg attester slashing")
   419→			}
   420→		}
   421→		for _, vs := range orphanedBlk.Block().Body().ProposerSlashings() {
